# contract: raw_users — privacy governance layer
columns = {
    "user_id":     {"class": "internal",    "policy": "allow"},
    "email":       {"class": "pii_direct",  "policy": "mask"},      # mask → sha256
    "home_zip":    {"class": "pii_quasi",   "policy": "tokenize"},  # k-anon bucket
    "order_total": {"class": "internal",    "policy": "allow"},
}
POLICIES = {"allow", "mask", "tokenize", "drop"}

def governance_gate(source_cols, contract):
    """Fail the pipeline if any live column is unclassified."""
    unclassified = [c for c in source_cols if c not in contract]
    bad_policy   = [c for c, m in contract.items()
                    if m["policy"] not in POLICIES]
    if unclassified:
        raise GovernanceError(f"BLOCKED: unclassified columns {unclassified}")
    if bad_policy:
        raise GovernanceError(f"BLOCKED: unknown policy on {bad_policy}")
    return {c: contract[c]["policy"] for c in source_cols}  # enforced plan

cost-capacity.code:
-- source contract SLA: orders must be < 2h stale, partitioned by _hour
{{ config(materialized='incremental', unique_key='order_id',
          incremental_strategy='insert_overwrite', partition_by={'field':'order_date','data_type':'date'}) }}

with fresh_orders as (
  select * from {{ source('ops','orders') }}
  {% if is_incremental() %}
    -- BUDGET: prune to the lookback window, never full-scan
    where _hour >= (select max(_hour) from {{ this }}) - interval '3' hour
  {% endif %}
),
guarded as (
  -- FRESHNESS GATE: quarantine rows older than the SLA instead of trusting them
  select *, case when _hour < now() - interval '2' hour then 'STALE' else 'OK' end as _gate
  from fresh_orders
)
select order_date, sum(amount) as revenue, count(*) as order_count
from guarded where _gate = 'OK'
group by order_date
